/* @lc app=leetcode id=3906 lang=kotlin */ class Solution { fun go(ds: List<Int>, path: Set<Int>, pos: Int, last: Int, tight: Boolean, memo: HashMap<Int, Long>): Long = if (pos == 16) 1L else memo.getOrPut((pos * 10 + last) * 2 + (if (tight) 1 else 0)) { (0..(if (tight) ds[pos] else 9)).sumOf { d -> if (pos in path) (if (d >= last) go(ds, path, pos + 1, d, tight && d == ds[pos], memo) else 0L) else go(ds, path, pos + 1, last, tight && d == ds[pos], memo) } } fun countGoodIntegersOnPath(l: Long, r: Long, directions: String): Long = directions.fold(listOf(0) to (0 to 0)) { (cells, rc), c -> (if (c == 'D') rc.first + 1 to rc.second else rc.first to rc.second + 1).let { nr -> (cells + (nr.first * 4 + nr.second)) to nr } }.first.toSet().let { path -> "%016d".format(r).map { it - '0' }.let { dr -> "%016d".format(l - 1).map { it - '0' }.let { dl -> go(dr, path, 0, 0, true, HashMap()) - go(dl, path, 0, 0, true, HashMap()) } } } }